import csv

refs = {
    "CHWPump02": "a39e93e1-f68f-5e9e-b836-56293fd89fa7",
    "Chiller02": "6041ce4e-9251-5a23-9103-a13dcc247d28",
    "SupplyFan_AHU01": "4693f367-6f23-5b26-868f-f17e866f28b6",
}

# Also grab units from catalog
units = {}
with open(CATALOG_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        tsid = row["timeseries_id"]
        for name, ref in refs.items():
            if ref in row.get("point_uri","") or ref == tsid:
                units[name] = row.get("unit")

print("units:", units)

totals = {name: 0.0 for name in refs}
counts = {name: 0 for name in refs}
with open(VALUES_CSV) as f:
    reader = csv.DictReader(f)
    for row in reader:
        tsid = row["timeseries_id"]
        ts = row["timestamp"]
        if not ts.startswith("2018-07-19"):
            continue
        val = row["value"]
        if val in (None, "", "None", "NaN"):
            continue
        for name, ref in refs.items():
            if ref == tsid or ref in tsid:
                try:
                    totals[name] += float(val)
                    counts[name] += 1
                except:
                    pass

print("totals:", totals)
print("counts:", counts)
best = max(totals, key=lambda k: totals[k])
print("best:", best, totals[best])
